//! 🧪️ Complete original refusal owners obey independent corpus accounting and physical close laws.
use semio_framework_job::{OriginalTurnFailure,StepContext};
use semio_framework_value::ValueError;
use semio_framework_diagnostic::Fault;
use semio_framework_job::{Generation,OperationId,StepBudget,RetainedCloneGrant,RetainedCloneProgress,root_cancel_token};
use semio_framework_value::{ValueRefusalKind,retirement::controlled::ControlledRetirement};
use semio_framework_value_testing_allocator as _;
#[derive(Debug,semio_framework_value::RetireOwned)]
struct DomainFixture{code:String,message:String,operand:u64,retained:RetainedCloneProgress}
impl semio_framework_job::OriginalDomainProjection for DomainFixture{
 fn projection_identity(&self)->usize{self.message.as_ptr()as usize}
 fn projection_view(&self,path:&[usize])->Result<semio_framework_job::OriginalDomainView<'_>,ValueError>{use semio_framework_job::OriginalDomainView as V;Ok(match path{[]=>V::IntrinsicObject(4),[0]=>V::IntrinsicText(&self.code),[1]=>V::IntrinsicText(&self.message),[2]=>V::IntrinsicNumber(semio_framework_value::Number::UInt(self.operand)),[3]=>V::IntrinsicObject(4),[3,index]if *index<4=>V::IntrinsicNumber(semio_framework_value::Number::UInt([self.retained.copied_items,self.retained.copied_bytes,self.retained.retained_capacity_bytes,self.retained.released_bytes][*index]as u64)),_=>return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original fixture projection path changed"))})}
 fn projection_key(&self,path:&[usize],index:usize)->Result<&str,ValueError>{match path{[]=>["code","message","operand","retainedProgress"].get(index).copied(),[3]=>["copiedItems","copiedBytes","retainedCapacityBytes","releasedBytes"].get(index).copied(),_=>None}.ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"original fixture projection key changed"))}
}
impl semio_framework_job::OriginalDomainFailure for DomainFixture{
 fn domain_code(&self)->&str{&self.code}
 fn domain_message(&self)->&str{&self.message}
 fn domain_retained_progress(&self)->RetainedCloneProgress{self.retained}
}

/// 📦️ Actual paid type erasure preserves the original domain and retires through one finite caller.
#[test]
fn original_turn_failure_domain_admission_preserves_full_source_and_paid_close(){
 use semio_framework_job::{OriginalDomainReservation,admit_original_domain_failure,original_domain_failure_demand,close_original_retained_step,OriginalDomainView as V};
 use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📦️domain.json")).unwrap();
 for copy in [1,3,64]{
  let stock=failure_source_stock();let((mut caller,mut original),initial)=semio_framework_trace::observe_heap_allocations_on_this_thread(||(OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,||Some(1000),1500,32768),Some(DomainFixture{code:corpus["domain"]["code"].as_str().unwrap().into(),message:corpus["domain"]["message"].as_str().unwrap().into(),operand:corpus["domain"]["operand"].as_str().unwrap().parse().unwrap(),retained:progress(&corpus["domain"]["retainedProgress"])})));
  let(mut born,mut freed)=(initial.requested_bytes,initial.released_bytes);let pointer=original.as_ref().unwrap().message.as_ptr();let identity=caller.turn(stock,|cx|Ok(cx.original_recipient_identity())).unwrap();let mut failure=None;let mut reservation=OriginalDomainReservation::<DomainFixture>::new();
  for row in corpus["cases"].as_array().unwrap(){let loan=RetainedCloneGrant{maximum_items:row["items"].as_u64().unwrap()as usize,maximum_capacity_bytes:row["capacity"].as_u64().unwrap()as usize,maximum_depth:row["depth"].as_u64().unwrap()as usize,..stock};caller.turn(stock,|cx|{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|actual|reservation.prepare(actual)));let prepared=result?;assert_eq!(prepared,row["prepare"].as_bool().unwrap());assert!(!heap.overflowed);if prepared{assert_eq!(heap.requested_bytes,original_domain_failure_demand::<DomainFixture>().capacity_bytes);assert_eq!(heap.released_bytes,0);assert_eq!(cx.fuel_remaining(),fuel-1);assert_eq!(cx.retained_progress().retained_capacity_bytes-before.retained_capacity_bytes,heap.requested_bytes);assert_eq!(cx.retained_progress().copied_bytes,before.copied_bytes);}else{assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.fuel_remaining(),fuel);assert_eq!(cx.retained_progress(),before);}assert_eq!(original.as_ref().unwrap().message.as_ptr(),pointer);born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!(cx.original_recipient_identity(),identity);Ok(())}).unwrap();}
  caller.turn(stock,|cx|{assert!(reservation.with_body(cx,|_,slot|{*slot=original.take();Ok(())})?.is_some());let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||admit_original_domain_failure(&mut reservation,cx));failure=result?;assert!(original.is_none());assert!(reservation.terminal_is_empty());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.fuel_remaining(),fuel-1);assert_eq!(cx.retained_progress().copied_items,before.copied_items+1);assert_eq!(cx.retained_progress().retained_capacity_bytes,before.retained_capacity_bytes);Ok(())}).unwrap();
  let failure=failure.unwrap();let domain=failure.primary_domain().unwrap();assert_eq!(domain.message().as_ptr(),pointer);assert_eq!(domain.projection().projection_identity(),pointer as usize);assert_eq!(domain.retained_progress(),progress(&corpus["domain"]["retainedProgress"]));assert!(failure.receipt_refusal.is_none());let((projection_identity,operand,key),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{use semio_framework_job::OriginalDomainProjection;(failure.projection_identity(),failure.projection_view(&[0,1,2]).unwrap(),failure.projection_key(&[0,1],2).unwrap())});assert_eq!(projection_identity,&failure as*const _ as usize);assert!(matches!(operand,V::IntrinsicNumber(semio_framework_value::Number::UInt(9007199254740993))));assert_eq!(key,"operand");assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  let(mut closing,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ControlledRetirement::new(failure).unwrap_or_else(|_|panic!("domain fixture controlled retirement unsupported")));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.cancel().cancel_now();
  for turn in 0..32768{if closing.terminal_is_empty(){break}let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,..stock};caller.turn(stock,|cx|{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|actual|close_original_retained_step(actual,closing.selected_demand(copy)?,|grant|{let result=closing.step(grant);semio_framework_value::RetainedWorkOutcome{result,work:closing.last_turn_work()}}).map(|step|step.progress())));let effects=result?;assert_eq!((heap.requested_bytes,heap.released_bytes),(effects.retained_capacity_bytes,effects.released_bytes));assert_eq!(cx.retained_progress(),before.checked_add(effects)?);assert_eq!(cx.fuel_remaining(),fuel-closing.last_turn_work());born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(turn<32767);assert!(cx.is_cancelled());assert_eq!(cx.original_recipient_identity(),identity);Ok(())}).unwrap();}
  assert!(closing.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(closing));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  for turn in 0..128{if caller.terminal_is_empty(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.retire_step(stock));let effects=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(effects.retained_capacity_bytes,effects.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(turn<127);}assert!(caller.terminal_is_empty());assert_eq!(born,freed);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(caller));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 }
}
fn failure_source_stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:134217728,maximum_capacity_bytes:268435456,maximum_release_bytes:536870912,maximum_depth:4096}}
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn grant(value:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:value["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:value["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:value["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:value["maximumDepth"].as_u64().unwrap()as usize}}
fn progress(value:&serde_json::Value)->RetainedCloneProgress{RetainedCloneProgress{copied_items:value["copiedItems"].as_u64().unwrap()as usize,copied_bytes:value["copiedBytes"].as_u64().unwrap()as usize,retained_capacity_bytes:value["retainedCapacityBytes"].as_u64().unwrap()as usize,released_bytes:value["releasedBytes"].as_u64().unwrap()as usize}}

/// 🧭️ Actual failed child accounting keeps the semantic pointer and complete overdraw refusal.
#[test]
fn original_turn_failure_debit_preserves_both_owned_causes(){
 use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
 let corpus=corpus();for row in corpus["cases"].as_array().unwrap(){let expected=progress(&row["primary"]["retainedProgress"]);let primary=ValueError::new(ValueRefusalKind::from_wire(row["primary"]["kind"].as_str().unwrap()).unwrap(),row["primary"]["message"].as_str().unwrap()).with_retained_progress(expected);let pointer=primary.message.as_ptr();let stock=failure_source_stock();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,||Some(1),1500,32768);let mut failure=None;
  caller.turn(stock,|cx|cx.with_original_work_loan(1,10,|cx|{let result=cx.with_retained_loan(grant(&row["grant"]),|cx|{let before=cx.retained_progress();let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||OriginalTurnFailure::debit_original(primary,cx));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(value.primary.message().as_ptr(),pointer);assert_eq!(value.primary.retained_progress(),expected);assert_eq!(cx.retained_progress(),before.checked_add(expected)?);assert_eq!(cx.fuel_remaining(),1);assert_eq!(value.receipt_refusal.as_ref().map(|error|error.kind.as_str()),row["expectedReceiptKind"].as_str());if let Some(error)=&value.receipt_refusal{assert_eq!(error.retained_progress(),expected)}failure=Some(value);Ok(())});assert!(result.is_ok());Ok(())})).unwrap();
  let mut owner=ControlledRetirement::new(failure.take().unwrap()).unwrap_or_else(|_|panic!("original failure retirement unsupported"));let closing=grant(&corpus["closeGrant"]);for turn in 0..100000{if owner.terminal_is_empty(){break}caller.turn(stock,|cx|{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(closing,|same|{let demand=owner.selected_demand(closing.maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(same,demand,|g|{let result=owner.step(g);semio_framework_value::RetainedWorkOutcome{result,work:owner.last_turn_work()}}).map(|step|step.progress())}));let effects=result?;assert_eq!((heap.requested_bytes,heap.released_bytes),(effects.retained_capacity_bytes,effects.released_bytes));assert!(turn<99999);Ok(())}).unwrap();}assert!(owner.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.retire(stock);
 }
}

/// 🍂️ Distinct original prose survives denied retirement and every narrow funded close frontier.
#[test]
fn original_turn_failure_paid_retirement_preserves_denied_sources(){
 let corpus=corpus();for copy in corpus["copyGrants"].as_array().unwrap(){let((failure,pointers),initial)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let primary=ValueError::new(ValueRefusalKind::UnsupportedOwner,"Primary original semantic cause 源🌊");let secondary=ValueError::new(ValueRefusalKind::InvariantViolated,"Distinct original receipt refusal 源🌊");let pointers=(primary.message.as_ptr(),secondary.message.as_ptr());({let original=OriginalTurnFailure::from(primary);OriginalTurnFailure{receipt_refusal:Some(secondary),context_refusal:None,..original}},pointers)});let mut born=initial.requested_bytes;let mut freed=initial.released_bytes;let(mut owner,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ControlledRetirement::new(failure).unwrap_or_else(|_|panic!("original pair retirement unsupported")));born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!(heap.requested_bytes,0);assert_eq!(heap.released_bytes,0);let closing=RetainedCloneGrant{maximum_copy_bytes:copy.as_u64().unwrap()as usize,..grant(&corpus["closeGrant"])};
  for denied in [RetainedCloneGrant{maximum_items:0,..closing},RetainedCloneGrant{maximum_depth:0,..closing}]{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(denied));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(result.map_or_else(|error|error.retained_progress()==Default::default(),|step|step.progress()==Default::default()));let original=owner.original().unwrap();assert_eq!((original.primary.message().as_ptr(),original.receipt_refusal.as_ref().unwrap().message.as_ptr()),pointers);}
  for turn in 0..100000{if owner.terminal_is_empty(){break}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(closing));let effects=step.unwrap().progress();assert!(effects.fits(closing));assert_eq!((heap.requested_bytes,heap.released_bytes),(effects.retained_capacity_bytes,effects.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(turn<99999,"[DEBUG] original failure retirement blocked at copy{} demand{:?} work{}",closing.maximum_copy_bytes,owner.selected_demand(closing.maximum_copy_bytes),owner.last_turn_work())}assert!(owner.terminal_is_empty());assert_eq!(born,freed);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 }
}

