/// 🛬️ Full receiving causes move inline and borrow their exact original fields without a post-refusal allocation.
#[test]
fn original_turn_failure_receiving_preserves_five_owned_causes(){
 use semio_framework_job::{OriginalReceivingPrimary,OriginalDomainProjection,OriginalDomainView as V};
 use semio_framework_value_native_owned::native_decoding::NativeConstructionStepFailure;
 let corpus=corpus();let wire=&corpus["receivingWire"];let row=&wire["primary"]["original"];
 let cause=|value:&serde_json::Value|ValueError::new(ValueRefusalKind::from_wire(value["kind"].as_str().unwrap()).unwrap(),value["message"].as_str().unwrap()).with_retained_progress(progress(&value["retainedProgress"]));
 for copy in [1,3,64]{
  let((original,receipt,context,pointers),initial)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let primary=cause(&row["primary"]);let quote=cause(&row["quoteRefusal"]);let allocation=cause(&row["allocationRefusal"]);let receipt=cause(&wire["receiptRefusal"]);let context=cause(&wire["contextRefusal"]);let pointers=[primary.message.as_ptr(),quote.message.as_ptr(),allocation.message.as_ptr(),receipt.message.as_ptr(),context.message.as_ptr()];(OriginalReceivingPrimary{primary:Some(primary),quote_refusal:Some(quote),allocation_refusal:Some(allocation),progress:progress(&row["retainedProgress"])},receipt,context,pointers)});
  let(failure,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut failure=OriginalTurnFailure::from(NativeConstructionStepFailure{progress:original.progress,primary:Some(original),receipt_refusal:Some(receipt)});failure.context_refusal=Some(context);failure});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  let original=failure.primary_receiving().unwrap();assert_eq!([original.primary.as_ref().unwrap().message.as_ptr(),original.quote_refusal.as_ref().unwrap().message.as_ptr(),original.allocation_refusal.as_ref().unwrap().message.as_ptr(),failure.receipt_refusal.as_ref().unwrap().message.as_ptr(),failure.context_refusal.as_ref().unwrap().message.as_ptr()],pointers);
  let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{assert!(matches!(failure.projection_view(&[0,0]).unwrap(),V::IntrinsicText("receiving")));for(index,name)in ["primary","quoteRefusal","allocationRefusal"].iter().enumerate(){assert_eq!(failure.projection_key(&[0,1],index).unwrap(),*name);assert!(matches!(failure.projection_view(&[0,1,index,1]).unwrap(),V::IntrinsicText(message)if message.as_ptr()==pointers[index]));}assert_eq!(failure.projection_key(&[0,1],3).unwrap(),"retainedProgress");});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  let(mut born,mut freed)=(initial.requested_bytes,initial.released_bytes);let mut owner=ControlledRetirement::retain(failure);let closing=RetainedCloneGrant{maximum_copy_bytes:copy,..grant(&corpus["closeGrant"])};
  for denied in [RetainedCloneGrant{maximum_items:0,..closing},RetainedCloneGrant{maximum_depth:0,..closing}]{let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(denied));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(owner.original().unwrap().primary_receiving().unwrap().primary.as_ref().unwrap().message.as_ptr(),pointers[0]);}
  for turn in 0..100000{if owner.terminal_is_empty(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(closing));let effects=result.unwrap().progress();assert!(effects.fits(closing));assert_eq!((heap.requested_bytes,heap.released_bytes),(effects.retained_capacity_bytes,effects.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(turn<99999,"[DEBUG] original failure retirement blocked at copy{} demand{:?} work{}",closing.maximum_copy_bytes,owner.selected_demand(closing.maximum_copy_bytes),owner.last_turn_work())}assert!(owner.terminal_is_empty());assert_eq!(born,freed);assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner)).1,Default::default());
 }
}

/// 🧾️ One real original caller retains the cumulative copy span independently of its last primary receipt.
#[test]
fn original_turn_failure_enclosing_effects_preserve_last_primary_and_same_caller_close(){
 use semio_framework_job::{OriginalJobFixtureCaller,OriginalDomainView as V};
 let law=corpus();let row=&law["effectSpan"];let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(91061),Generation(7),stock,||Some(1000),1500,65536);let mut target=[0u8;24];let source=[7u8;24];
 let(mut failure,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(stock,|cx|{
  let before=cx.retained_progress();let recipient=cx.original_recipient_identity();for range in [0..8,8..17]{target[range.clone()].copy_from_slice(&source[range.clone()]);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:range.len(),..Default::default()})?;}
  target[17..].copy_from_slice(&source[17..]);let last=RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()};cx.consume_retained(last)?;
  let mut failure=OriginalTurnFailure::from(ValueError::literal(ValueRefusalKind::InvalidValue,"Last original semantic 源").with_retained_progress(last));let after=cx.retained_progress();failure.effects=RetainedCloneProgress{copied_items:after.copied_items.checked_sub(before.copied_items).unwrap(),copied_bytes:after.copied_bytes.checked_sub(before.copied_bytes).unwrap(),retained_capacity_bytes:after.retained_capacity_bytes.checked_sub(before.retained_capacity_bytes).unwrap(),released_bytes:after.released_bytes.checked_sub(before.released_bytes).unwrap()};assert_eq!(cx.original_recipient_identity(),recipient);Ok(failure)
 }).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(target,source);assert_eq!(failure.primary.retained_progress().copied_bytes,row["last"]["copiedBytes"].as_u64().unwrap()as usize);assert_eq!(failure.retained_progress().copied_bytes,row["whole"]["copiedBytes"].as_u64().unwrap()as usize);assert_eq!(caller.receipt(),failure.retained_progress());
 let pointer=failure.primary.message().as_ptr();let projected=semio_framework_job::project_original_turn_failure(&failure,&[1,1]).unwrap();assert!(matches!(projected,V::IntrinsicNumber(semio_framework_value::Number::UInt(24))));assert_eq!(failure.primary.message().as_ptr(),pointer);
 failure.receipt_refusal=Some(ValueError::literal(ValueRefusalKind::InvariantViolated,"Distinct original receipt refusal"));failure.context_refusal=Some(ValueError::literal(ValueRefusalKind::WorkLimit,"Distinct original context refusal"));
 let mut owner=ControlledRetirement::retain(failure);for _ in 0..100000{if owner.terminal_is_empty(){break}caller.turn(stock,|cx|{let demand=owner.next_demand(7)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let result=owner.step(grant);semio_framework_value::RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;Ok(())}).unwrap();}assert!(owner.terminal_is_empty());caller.retire(stock);
}

/// 🎟️ Original typed Box custody preserves exact physical backing under every denial.
fn assert_original_diagnostic_box<T:semio_framework_value::retirement::RetireOwned>(make:impl FnOnce()->Box<T>,law:&serde_json::Value){
 use semio_framework_value::retirement::{RetireOwned,RetirementStep,original_box::BoxOriginal};
 use semio_framework_value_testing_allocator::{observe_retirement_allocations,refuse_one_allocation_on_this_thread};
 let grant=grant(&law["grant"]);let(params,initial)=semio_framework_trace::observe_heap_allocations_on_this_thread(make);
  assert!(!initial.overflowed);let mut original=Some(BoxOriginal::from_original(params));let pointer=original.as_ref().unwrap().identity();let demand=original.as_ref().unwrap().get().boxed_original_demands().unwrap().unwrap();assert_eq!(demand.copy_bytes,0);
  for axis in ["items","capacity","depth"]{let mut denied=grant;match axis{"items"=>denied.maximum_items=0,"capacity"=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,_=>denied.maximum_depth=0}let(turn,heap)=observe_retirement_allocations(||<T as RetireOwned>::boxed_original_retirement(&mut original,denied));assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0);assert_eq!(heap,(0,0));assert_eq!(original.as_ref().unwrap().identity(),pointer);}
  let((turn,refused),heap)=observe_retirement_allocations(||refuse_one_allocation_on_this_thread(||<T as RetireOwned>::boxed_original_retirement(&mut original,grant)));assert_eq!(refused,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);assert!(matches!(turn.result,Err(error)if error.kind==ValueRefusalKind::AllocationFailed));assert_eq!(original.as_ref().unwrap().identity(),pointer);
  let(turn,heap)=observe_retirement_allocations(||<T as RetireOwned>::boxed_original_retirement(&mut original,grant));let(mut cursor,p)=turn.result.unwrap().unwrap();assert!(original.is_none());assert_eq!(turn.work,1);assert_eq!(p.copied_bytes,0);assert_eq!(heap,(p.retained_capacity_bytes,0));let mut born=initial.requested_bytes+p.retained_capacity_bytes;let mut released=initial.released_bytes;
  for turn in 0..law["maximumTurns"].as_u64().unwrap(){if cursor.terminal_is_empty(){break}let demand=cursor.next_demand(0).unwrap();assert_eq!(demand.copy_bytes,0);for axis in ["items","release","depth"]{if axis=="release"&&demand.release_bytes==0{continue}let mut denied=grant;match axis{"items"=>denied.maximum_items=0,"release"=>denied.maximum_release_bytes=demand.release_bytes-1,_=>denied.maximum_depth=0}let(step,heap)=observe_retirement_allocations(||cursor.close_step(denied));assert!(matches!(step,RetirementStep::BudgetExhausted));assert_eq!(step.work(),0);assert_eq!(heap,(0,0));}
   let(step,heap)=observe_retirement_allocations(||cursor.close_step(grant));let p=match step{RetirementStep::Progress(p,1)=>p,_=>panic!("actual parameter frontier must report its own work")};assert!(p.fits(grant));assert_eq!(p.copied_bytes,0);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;released+=heap.1;assert!(turn+1<law["maximumTurns"].as_u64().unwrap());
  }assert!(cursor.terminal_is_empty());let release=cursor.terminal_release_bytes().unwrap();let(_,heap)=observe_retirement_allocations(||drop(cursor));assert_eq!(heap,(0,release));released+=heap.1;assert_eq!(born,released);
}
fn diagnostic_box_law()->serde_json::Value{let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/params-box.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/params-box.schema.json")).unwrap();for(key,value)in law.as_object().unwrap(){assert_eq!(&schema["properties"][key]["const"],value)}law}
/// 🎟️ Real boxed parameters close their individual String, row, Vec and original shell allocations.
#[test]
fn original_fault_params_box_has_fallible_zero_copy_custody_and_exact_backing_close(){let law=diagnostic_box_law();for row in law["cases"].as_array().unwrap(){assert_original_diagnostic_box(||Box::new(semio_framework_diagnostic::FaultParams(row.as_array().unwrap().iter().map(|pair|(pair[0].as_str().unwrap().to_owned(),pair[1].as_str().unwrap().to_owned())).collect())),&law)}}
/// 🎯️ Each original scope field transfers once before the same original Box can release.
#[test]
fn original_fault_scope_box_has_fallible_zero_copy_custody_and_exact_backing_close(){let law=diagnostic_box_law();for row in law["scopeCases"].as_array().unwrap(){assert_original_diagnostic_box(||Box::new(semio_framework_diagnostic::FaultScope{plugin_id:row["pluginId"].as_str().map(str::to_owned),app_id:row["appId"].as_str().map(str::to_owned),instance_id:row["instanceId"].as_str().map(str::to_owned),module:row["module"].as_str().map(str::to_owned),body_key:row["bodyKey"].as_str().map(str::to_owned)}),&law)}}
